import{_ as E,C as s,o as e,c as g,E as a,a4 as i,b as d,w as l,a as n,a5 as o}from"./chunks/framework.2-Vke5-n.js";const B=JSON.parse('{"title":"はじめての非機能要件 第一部 全体プロセス編","description":"","frontmatter":{"sidebarDepth":4,"title":"はじめての非機能要件 第一部 全体プロセス編","author":"フューチャー株式会社","head":[["meta",{"name":"keywords","content":"非機能要件定義"}]]},"headers":[],"relativePath":"documents/forNFR/overview.md","filePath":"documents/forNFR/overview.md"}'),p={name:"documents/forNFR/overview.md"};function f(A,t,x,u,b,y){const h=s("page-title"),r=s("Mermaid");return e(),g("div",null,[a(h),t[2]||(t[2]=i('<h2 id="what" tabindex="-1">What（非機能要件とは何か） <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What（非機能要件とは何か） {#what}&quot;">​</a></h2><h3 id="非機能とは" tabindex="-1">非機能とは <a class="header-anchor" href="#非機能とは" aria-label="Permalink to &quot;非機能とは&quot;">​</a></h3><p>機能と非機能の違いを整理すると、次の通りである。</p><table tabindex="0"><thead><tr><th style="text-align:left;">区分</th><th style="text-align:left;">説明</th><th style="text-align:left;">ECサイトでの例</th></tr></thead><tbody><tr><td style="text-align:left;">機能</td><td style="text-align:left;">システムの具体的な振る舞いやロジックそのもの</td><td style="text-align:left;">・商品一覧を取得する<br>・商品を購入する</td></tr><tr><td style="text-align:left;">非機能</td><td style="text-align:left;">その機能がどのような品質で提供されるかを支える特性</td><td style="text-align:left;">・【性能】注文の確定結果がすぐ返ってくる<br>・【可用性】アクセスが多いときもダウンせず購入できる<br>・【セキュリティ】通信内容が第三者に漏れない</td></tr></tbody></table><p>非機能には、機能と対比した次の2つの性質がある。</p><ul><li><strong>横断的である</strong>: 個々の機能に一対一で紐づかず、システム全体を横断する関心事である。そのため、画面や機能の洗い出しからは抜け落ちやすい</li><li><strong>どの程度を問う</strong>: 機能が「実現できる / できない」という二値であるのに対し、非機能は「どれだけ速いか」「どれだけ止まらないか」という度合いを問う。だからこそ、要件は定量的に表現する必要がある</li></ul><div class="tip custom-block"><p class="custom-block-title">非機能に類似する用語</p><p>「非機能」は「品質特性」「アーキテクチャ特性」「イリティ」などとも呼ばれる。各呼称の定義の違いは <a href="./appendix.html#非機能に類似する用語">Appendix: 非機能に類似する用語</a> を参照。</p></div><div class="info custom-block"><p class="custom-block-title">参考</p><p><a href="https://future-architect.github.io/articles/20260617a/" target="_blank" rel="noreferrer">非機能テストを記号接地する</a></p></div><h3 id="非機能要件の位置づけ" tabindex="-1">非機能要件の位置づけ <a class="header-anchor" href="#非機能要件の位置づけ" aria-label="Permalink to &quot;非機能要件の位置づけ&quot;">​</a></h3><p>システムのアーキテクチャは、いくつかの要因によって方向づけられる。こうした要因をアーキテクチャドライバと呼び、非機能要件はその代表的なひとつである。<br> アーキテクチャドライバは次の要素から構成される。</p>',10)),(e(),d(o,null,{default:l(()=>[a(r,{id:"mermaid-81",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20theme%3A%20neutral%0A%20%20layout%3A%20dagre%0A%20%20look%3A%20handDrawn%0A%20%20flowchart%3A%0A%20%20%20%20nodeSpacing%3A%20100%0A---%0Aflowchart%20TB%0A%20%20%20%20AD%5B%22%E3%82%A2%E3%83%BC%E3%82%AD%E3%83%86%E3%82%AF%E3%83%81%E3%83%A3%E3%83%89%E3%83%A9%E3%82%A4%E3%83%90%22%5D%0A%20%20%20%20FR%5B%22%E4%B8%BB%E8%A6%81%E6%A9%9F%E8%83%BD%E8%A6%81%E4%BB%B6%3Cbr%2F%3E%EF%BC%88%E6%89%80%E4%B8%8E%E3%81%AE%E5%85%A5%E5%8A%9B%E3%83%BB%E7%AF%84%E5%9B%B2%E5%A4%96%EF%BC%89%22%5D%0A%0A%20%20%20%20subgraph%20SCOPE%5B%22%E6%9C%AC%E3%82%AC%E3%82%A4%E3%83%89%E3%83%A9%E3%82%A4%E3%83%B3%E3%81%AE%E3%82%B9%E3%82%B3%E3%83%BC%E3%83%97%22%5D%0A%20%20%20%20%20%20%20%20NFR%5B%22%E9%9D%9E%E6%A9%9F%E8%83%BD%E8%A6%81%E4%BB%B6%3Cbr%2F%3E%EF%BC%88%E4%B8%BB%E5%AF%BE%E8%B1%A1%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20CP%5B%22%E5%88%B6%E7%B4%84%22%5D%0A%20%20%20%20%20%20%20%20AC%5B%22%E3%81%9D%E3%81%AE%E4%BB%96%E3%81%AE%E9%96%A2%E5%BF%83%E4%BA%8B%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20AD%20--%3E%20FR%0A%20%20%20%20AD%20--%3E%20NFR%0A%20%20%20%20AD%20--%3E%20CP%0A%20%20%20%20AD%20--%3E%20AC%0A%20%20%20%20CP%20--%3E%20BC%5B%22%E3%83%93%E3%82%B8%E3%83%8D%E3%82%B9%E5%88%B6%E7%B4%84%22%5D%0A%20%20%20%20CP%20--%3E%20TC%5B%22%E6%8A%80%E8%A1%93%E5%88%B6%E7%B4%84%22%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23fff3b0%2Cstroke%3A%23333%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20inscope%20fill%3A%23EBE5FF%2Cstroke%3A%23B299FF%3B%0A%20%20%20%20classDef%20input%20fill%3A%23f0f0f0%2Cstroke%3A%23bbbbbb%2Ccolor%3A%23888888%2Cstroke-dasharray%3A4%203%3B%0A%0A%20%20%20%20class%20NFR%20primary%3B%0A%20%20%20%20class%20CP%2CAC%2CBC%2CTC%20inscope%3B%0A%20%20%20%20class%20FR%20input%3B%0A%0A%20%20%20%20style%20SCOPE%20fill%3Anone%2Cstroke%3A%23B299FF%2Cstroke-dasharray%3A5%205%3B%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=i('<p>非機能要件以外の要素は次の通りである。</p><ul><li><strong>主要機能要件</strong><br> アーキテクチャや技術選定、ひいてはインフラ構成やコストに影響を与えるユースケースを指す。実現のためにシステムの構造が大きく左右される機能が該当する。一見単純に見える機能でも、アーキテクチャを規定するのであれば含まれる。 <ul><li><strong>例1: 巨大ファイルのアップロード:</strong> アプリサーバーを経由する通常のアップロードではメモリやタイムアウトに乗り切らないため、S3への署名付きURL方式を採ることが多い。するとリクエストがアプリを通らず従来の同期的なウィルスチェックが効かなくなるため、アップロード後にS3イベントで非同期スキャンを走らせる仕組みや隔離用バケット、専用のネットワーク経路・IAM/バケットポリシーを別途設計する必要が生じ、インフラ構成とコストに波及する。</li><li><strong>例2: リアルタイムな通知:</strong> 都度リクエストを投げるHTTPでは要件を満たせず、WebSocket などの常時接続が必要となると話が大きくなる。各接続を保持するステートフルな構成や、スケールアウト時のセッション共有やメッセージ配信のためのPub/Sub基盤、WebSocketに対応したロードバランサーまで含めた設計が必要になる。</li></ul></li><li><strong>制約</strong><br> 機能要件や非機能要件を実現するうえでの前提条件であり、次の2つに分けられる。 <ul><li><strong>ビジネス制約</strong>: プロジェクトの予算やスケジュール、体制、社内規程、コンプライアンス要件など</li><li><strong>技術制約</strong>: 使用する環境（CSP やオンプレ）、言語、フレームワーク、ライブラリの制約やセキュリティポリシーなど</li></ul></li><li><strong>その他の関心事</strong><br> チームメンバーのスキル、組織内のナレッジ、技術の採用実績、プロジェクト規模などが該当する。</li></ul><h4 id="本ガイドラインのスコープ" tabindex="-1">本ガイドラインのスコープ <a class="header-anchor" href="#本ガイドラインのスコープ" aria-label="Permalink to &quot;本ガイドラインのスコープ&quot;">​</a></h4><p>本ガイドラインは、アーキテクチャドライバのうち非機能要件を主対象とする。各要素の扱いは次の通りである。</p><table tabindex="0"><thead><tr><th style="text-align:left;">要素</th><th style="text-align:left;">分類</th><th style="text-align:left;">本ガイドラインでの扱い</th></tr></thead><tbody><tr><td style="text-align:left;">非機能要件</td><td style="text-align:left;">主対象</td><td style="text-align:left;">定義する成果物。</td></tr><tr><td style="text-align:left;">制約</td><td style="text-align:left;">考慮対象</td><td style="text-align:left;">非機能要件を左右する前提として、洗い出し・考慮する。</td></tr><tr><td style="text-align:left;">その他の関心事</td><td style="text-align:left;">〃</td><td style="text-align:left;">〃</td></tr><tr><td style="text-align:left;">主要機能要件</td><td style="text-align:left;">対象外</td><td style="text-align:left;">入力として参照するに留め、定義自体は範囲外とする。</td></tr></tbody></table><h3 id="非機能要件定義とは" tabindex="-1">非機能要件定義とは <a class="header-anchor" href="#非機能要件定義とは" aria-label="Permalink to &quot;非機能要件定義とは&quot;">​</a></h3><p>本ガイドラインが対象とする「非機能要件定義」とは、単に品質特性の項目を一覧化する作業ではない。ビジネスの文脈や機能要件、既存の制約を入力・前提として踏まえたうえで、次の3つを行っていく営みである。</p><ol><li>システムにとって本当に重要な非機能要件（またはアーキテクチャドライバ）を見極める</li><li>曖昧な期待を定量的で検証可能な要件へ変換する</li><li>関係者間で合意する</li></ol><p>限られたコストと期間の中でトレードオフを見極め、何を優先し、何を諦めるかを関係者と合意することが重要である。</p><h2 id="why" tabindex="-1">Why（なぜ定義するのか） <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why（なぜ定義するのか） {#why}&quot;">​</a></h2><p>機能要件を定義するだけでは、ビジネスが求めるシステム品質は担保できない。システムがどのような品質・状態で動作するかという非機能要件を明文化し、関係者と合意することには、主に次の5つの目的がある。これらは大きく、要求、実現、継承の3つに分けられる。</p><h3 id="要求-何を、どれくらいの予算で作るかを決める" tabindex="-1">要求（何を、どれくらいの予算で作るかを決める） <a class="header-anchor" href="#要求-何を、どれくらいの予算で作るかを決める" aria-label="Permalink to &quot;要求（何を、どれくらいの予算で作るかを決める）&quot;">​</a></h3><ol><li><strong>【要件定義】</strong> 機能要件からは導出できない「暗黙の期待」を可視化するため <ul><li><a href="#what">What章</a>で述べたとおり、非機能はシステムを横断する関心事で、画面や機能の洗い出しからは抜け落ちやすい。「いつでも使えて当然」といった暗黙の期待を明示的な要件として引き出すことで、「どこまでの品質を作るか」の認識のズレを防ぐ。</li></ul></li><li><strong>【見積もり】</strong> コスト・規模見積もりの根拠を与えるため <ul><li>性能・可用性・拡張性などの非機能要件は、必要なサーバー規模やサービス構成、冗長化の範囲を左右し、インフラの規模とコストを決める。非機能要件はインフラの償却費や運用委託料に直結する、いわば「費用を決めるもの」でもある。非機能要件が定まって初めて、精度のある費用・体制を見積もれる。</li></ul></li></ol><h3 id="実現-正しく作り、保証する" tabindex="-1">実現（正しく作り、保証する） <a class="header-anchor" href="#実現-正しく作り、保証する" aria-label="Permalink to &quot;実現（正しく作り、保証する）&quot;">​</a></h3><ol start="3"><li><strong>【設計】</strong> アーキテクチャの構造を決定し、致命的な手戻りを防ぐため <ul><li>非機能要件、特に性能・可用性・セキュリティ・拡張性は、インフラ構成やミドルウェア選定、データモデルといったシステムの構造そのものを規定する。そのため構築フェーズ以降に変更や追加が生じると、アーキテクチャレベルの見直しに直結し、多大なコスト増や遅延を招く。だからこそ早期に確定させる必要がある。</li></ul></li><li><strong>【テスト】</strong> 品質保証のための「非機能テスト」で客観的な基準を設けるため <ul><li>要求品質を満たすかの証明には、負荷テスト、セキュリティ診断、可用性テストなどが欠かせない。「レスポンスが速いこと」といった定性的な表現ではなく、「ピーク時の画面表示は90％が3秒以内」といった定量目標を定めて初めて、テスト計画の作成と客観的な合否判定ができる。</li></ul></li></ol><h3 id="継承" tabindex="-1">継承（引き継ぎや刷新に活かす） <a class="header-anchor" href="#継承" aria-label="Permalink to &quot;継承（引き継ぎや刷新に活かす） {#継承}&quot;">​</a></h3><ol start="5"><li><strong>【保守・刷新】</strong> 保守運用や将来のシステム刷新に引き継ぐため <ul><li>明文化された非機能要件は、構築時だけでなく、その後の保守運用や次期システムへの刷新でも参照される資産になる。保守体制が交代しても「なぜこの可用性水準・構成なのか」という意図を伝える。リプレイス時には、次期システムの要求水準を定めるベースラインとなる。文書化されていなければ、後任は設計意図を推測で補うことになり、品質劣化や過剰・過小な作り込みを招く。</li></ul></li></ol><p>これら5つの目的を通じて、非機能要件定義は結果として、プロジェクトの実現性やコストのリスクを早期に潰しこむ活動にもなる。</p><div class="tip custom-block"><p class="custom-block-title">アジャイル開発の場合</p><p>開発方式が変わっても、ここまでの5つの目的は変わらない。アジャイルでも非機能要件を定義する必要性は失われない。むしろ「動くものを早く出す」を口実に非機能を後回しにすると、アーキテクチャ変更という土台からのやり直しに陥るリスクがある。変わるのは いつ・どの粒度で決めるか であって、実施の要否ではない。</p></div><h3 id="テストフェーズとの連携" tabindex="-1">テストフェーズとの連携 <a class="header-anchor" href="#テストフェーズとの連携" aria-label="Permalink to &quot;テストフェーズとの連携 {#テストフェーズとの連携}&quot;">​</a></h3><p>非機能要件は、テストで検証されて初めて担保されたと言える。どの非機能要件が、どのテストで検証されるかの紐づけを理解しておきたい。これにより、次の双方向のチェックができる。</p><ul><li><strong>要件 → テスト</strong>: 合意しようとしている要件が、テストで検証可能な数値目標になっているかを確認できる</li><li><strong>テスト → 要件</strong>: テスト計画から逆算して、抜けている非機能要件を洗い出せる</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">非機能要求項目</th><th style="text-align:left;">テスト種別</th><th style="text-align:left;">主な検証項目</th></tr></thead><tbody><tr><td style="text-align:left;">可用性</td><td style="text-align:left;">障害テスト</td><td style="text-align:left;">冗長性、フェイルオーバー、バックアップ＆リストア</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">DR切替/切戻テスト</td><td style="text-align:left;">RTO（目標復旧時間）、RPO（目標復旧時点）</td></tr><tr><td style="text-align:left;">性能・拡張性</td><td style="text-align:left;">ボリュームテスト</td><td style="text-align:left;">レイテンシ・限界データ量</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">ラッシュテスト</td><td style="text-align:left;">スループット</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">ストレステスト</td><td style="text-align:left;">限界負荷性能</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">スパイクテスト</td><td style="text-align:left;">突発負荷性能</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">ロングランテスト</td><td style="text-align:left;">耐久性</td></tr><tr><td style="text-align:left;">運用・保守性</td><td style="text-align:left;">運用テスト</td><td style="text-align:left;">監視アラート、計画停止、縮退稼働</td></tr><tr><td style="text-align:left;">移行性</td><td style="text-align:left;">移行テスト</td><td style="text-align:left;">環境移行、データ移行</td></tr><tr><td style="text-align:left;">セキュリティ</td><td style="text-align:left;">脆弱性診断テスト</td><td style="text-align:left;">アプリケーション脆弱性</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">ペネトレーションテスト</td><td style="text-align:left;">侵入可能性</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">アクセス権限・認証テスト</td><td style="text-align:left;">権限制御</td></tr><tr><td style="text-align:left;">使用性・アクセシビリティ</td><td style="text-align:left;">アクセシビリティテスト</td><td style="text-align:left;">適合レベルごとの達成基準</td></tr></tbody></table><p>要件を定義したら、まずはそれがこの表のどこで検証されるかを確かめると良い。対応するテストが思い当たらない場合は、どのようにそれを検証するかをセットで考えるべきである。</p><h2 id="when" tabindex="-1">When（いつ合意すべきか） <a class="header-anchor" href="#when" aria-label="Permalink to &quot;When（いつ合意すべきか） {#when}&quot;">​</a></h2><p>非機能要件はいつ合意すべきか。結論から言えば、一度に決めきるのではない。フェーズの解像度に合わせて段階的に具体化し、できる限り早期にすり合わせる &quot;シフトレフト&quot; の考え方で行う。</p><p>というのも現場では、非機能要件を決めようとする時に、相反する2つの力が働くためである。</p><ul><li><strong>早く決めたい</strong>: 非機能はアーキテクチャを規定するため、早期に固めたい</li><li><strong>まだ決めきれない</strong>: 要件定義の段階ではアーキテクチャ像が定まっておらず、詳細を決めきれない</li></ul><p>後者に引きずられて「基本設計で決めればよい」と先送りすると、基本設計で「その要件にはインフラの抜本的な変更が必要」となり、予算超過やスケジュール遅延を招く。だからこそ段階的に、かつ早期に、大枠から見切っていく必要がある。</p><h3 id="フェーズごとの段階的具体化" tabindex="-1">フェーズごとの段階的具体化 <a class="header-anchor" href="#フェーズごとの段階的具体化" aria-label="Permalink to &quot;フェーズごとの段階的具体化&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">フェーズ</th><th style="text-align:left;">粒度</th><th style="text-align:left;">このフェーズで決めること</th><th style="text-align:left;">主なアクション</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">提案〜グラウンドデザイン</td><td style="text-align:left;">方針レベル</td><td style="text-align:left;">アーキテクチャの骨格と大枠の予算・体制</td><td style="text-align:left;">・重要ドライバを特定（クラウド/オンプレ、マルチリージョン要否、特別なセキュリティ要件（PCI-DSS準拠）など）<br>・コストとのトレードオフをビジネス層に提示し期待値を調整</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">要件定義</td><td style="text-align:left;">数値レベル</td><td style="text-align:left;">開発・テストの基準となる定量目標</td><td style="text-align:left;">・網羅的な洗い出し<br>・曖昧な表現（例: システムが止まらないこと）を定量値へ（例: RPO○時間・RTO○時間）<br>・利害関係者（開発、インフラ、運用、顧客）間で合意</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">基本設計以降</td><td style="text-align:left;">検証・確定</td><td style="text-align:left;">定義した要件の実現可能性</td><td style="text-align:left;">・PoC・負荷テスト<br>・セキュリティ診断で継続的に検証<br>・現実と乖離すればビジネス側と再調整</td></tr></tbody></table><p>全フェーズを通じて重要なのが期待値のコントロールである。確度の低い要件は、幅を持たせる・低めに置くなどしておきたい。実現できるか確かめないまま、背伸びした目標値（例: 可用性99.99％）を「確定」として約束してしまうと、後で下方修正する際に「なぜ下げるのか」の説明コストが大きいためである。目標は、上げる分には受け入れられやすいが、下げるのは難しい。</p><p>また、後続フェーズで手戻りが重なると、顧客に「あの時の合意は何だったのか」という不信を生み、信頼関係そのものを損なう。だからこそ、確度に応じて期待値を置き、万が一覆す必要があっても利害関係者へのサプライズを最小限に抑えることを意識すべきである。覆す必要がある場合も、カジュアルに申し出るのではなく、事業前提の変化や実測との乖離といった正当な理由を必ず添えて説明する。</p><h3 id="合意の場をどう設計するか" tabindex="-1">合意の場をどう設計するか <a class="header-anchor" href="#合意の場をどう設計するか" aria-label="Permalink to &quot;合意の場をどう設計するか&quot;">​</a></h3><p>非機能要件の合意は、想像以上に時間がかかる。仮に会議で同期的に議論すべき重点項目が20個あり、1項目20分で済むとしても6〜7時間。手戻りやバッファを見込めば十数時間に達する。週1回・1時間の会議なら十数回、2〜3か月に及び、要件定義フェーズに収まりきらない可能性がある。</p><p>だからこそ、次の2点が要る。</p><ul><li><strong>シフトレフト</strong>: 合意の場を要件定義の後半に固めず、可能な限り前倒しで持ち始める</li><li><strong>メリハリをつける</strong>: 全項目を会議で均等に扱わず、重要な要件は同期で議論し、それ以外は書面・非同期で確認する（重要度による絞り込みは <a href="#step4">How章 STEP4</a> を参照）</li></ul><div class="tip custom-block"><p class="custom-block-title">アジャイル開発の場合</p><p>アジャイルでは、非機能要件を一度に確定させる必要はない。ただし、アーキテクチャを規定する重要な非機能ドライバ（性能・可用性・セキュリティ・拡張性）は、後回しにすると機能開発が誤った前提で積み上がり、後で崩れてしまう。そのため方針レベルでは早期の見極めが必要である。一方で数値目標を全て決めきる必要はない。幅を持たせて、スプリントの反復で継続的に具体化していく。</p></div><h2 id="who" tabindex="-1">Who（だれが主体で、だれと合意するのか） <a class="header-anchor" href="#who" aria-label="Permalink to &quot;Who（だれが主体で、だれと合意するのか） {#who}&quot;">​</a></h2><p>非機能要件は、関係する利害関係者を漏れなく巻き込んで合意形成する必要がある。ただし、非機能要件を決めるモチベーションは通常システム構築側にしかない。そのため、構築側が主体性とオーナーシップを持って、議論をリードしなければならない。</p><h3 id="巻き込むべき利害関係者" tabindex="-1">巻き込むべき利害関係者 <a class="header-anchor" href="#巻き込むべき利害関係者" aria-label="Permalink to &quot;巻き込むべき利害関係者&quot;">​</a></h3><p>各利害関係者は、非機能要件の前提だけでなく、制約（予算・社内規程・技術標準・コンプライアンスなど）も持ち寄る。制約の出所は、非機能要件とは別の担当者（法務・CCoE・セキュリティ部門など）であることも多い（制約の洗い出しは <a href="#step3">How章 STEP3</a> を参照）。</p><table tabindex="0"><thead><tr><th style="text-align:left;">利害関係者</th><th style="text-align:left;">役割・提供する情報</th></tr></thead><tbody><tr><td style="text-align:left;">業務担当者</td><td style="text-align:left;">予算を計画し、システム停止時の影響度や業務ピーク時のトラフィック特性（イベントや決算期のアクセス増など）の前提を提示する。</td></tr><tr><td style="text-align:left;">IT部門（情シス）</td><td style="text-align:left;">企業全体のセキュリティポリシー、ネットワークポリシー、全社標準規約、他システムとの連携制約などを提示する。</td></tr><tr><td style="text-align:left;">セキュリティ部門</td><td style="text-align:left;">全社セキュリティポリシー・規程に基づきリスク評価と承認を担う。昨今は情シスと分離され牽制の立場を取ることが多く、審査に時間がかかるため早めに巻き込みリードタイムを確保する。</td></tr><tr><td style="text-align:left;">運用保守の引き継ぎ先</td><td style="text-align:left;">リリース後に監視・運用する担当として、アラート通知要件、バックアップ頻度、障害時の対応フローなどを提示する。</td></tr><tr><td style="text-align:left;">（リプレイスの場合）<br>現行システムの運用者</td><td style="text-align:left;">トラフィック実績、過去の障害履歴、ボトルネックなど、机上では見えない生きたデータと課題を提供する。</td></tr></tbody></table><h3 id="担当者を特定し、合意する" tabindex="-1">担当者を特定し、合意する <a class="header-anchor" href="#担当者を特定し、合意する" aria-label="Permalink to &quot;担当者を特定し、合意する&quot;">​</a></h3><p>利害関係者の&quot;役割&quot;は挙げられても、実際に誰がその役割を担うかは自明でないことが多い。まず役割ごとに該当者を探し、「誰が何に責任を持つか」を関係者間で決めることから始める。</p><p>該当者が不明の場合（例: 運用保守の引き継ぎ先が未定）は、構築側が仮説の上で想定を代弁し、後日引き継ぐ前提で進める。</p><div class="tip custom-block"><p class="custom-block-title">決裁権限が顧客の外・上位にあるとき</p><p>顧客が持株会社傘下の事業会社、親会社を持つ子会社、あるいは外資系の日本支社である場合、非機能要件の決裁権限やポリシーが、目の前の顧客ではなく親会社・グローバル本社にあることがある。目の前の担当者と合意しても、上位でひっくり返るリスクがあるため、次を意識する。</p><ul><li><strong>決裁権限の所在を早期に確認する</strong>: 目の前の担当者が最終決定者とは限らない。上位の承認が要るなら、その承認も合意プロセスに織り込む</li><li><strong>上位・グローバルの制約を洗い出す</strong>: 全社ポリシー、技術標準、データの居住性、調達ルールなど。見落とすと後で覆る（制約の洗い出しは <a href="#step3">How章 STEP3</a> を参照）</li><li><strong>リードタイムを見込む</strong>: 時差・言語・海外の承認プロセスにより、合意・承認には時間がかかる。早めに着手する</li></ul></div><h3 id="利害関係者との調整" tabindex="-1">利害関係者との調整 <a class="header-anchor" href="#利害関係者との調整" aria-label="Permalink to &quot;利害関係者との調整&quot;">​</a></h3><p>非機能要件の合意窓口は、提案から要件定義まで、顧客側の同じ推進担当者になることが多い。非機能要件だけを要件定義とは別の担当者に切り出せるのは、リソースの潤沢な組織に限られる。通常は、要件定義を担うその人が非機能要件も扱う。</p><p>一方で、フェーズごとに巻き込むべき利害関係者が増えることは多い。</p><ol><li><strong>提案〜グラウンドデザイン</strong><ul><li>窓口はリード担当者だが、予算・方針は事業責任者・経営層の承認を要する。場合によっては合意形成を促す資料作成を支援することもある</li></ul></li><li><strong>要件定義</strong><ul><li>詳細を詰めるため、IT部門・運用部門が加わる場合もある</li><li>セキュリティ部門の承認は審査プロセスを伴い時間がかかるため、（1）〜（2）で早めに着手する</li></ul></li><li><strong>基本設計以降</strong><ul><li>新たな合意相手は出ない。要件はFix済みで、乖離時のみメインの担当者と再調整する</li><li>（ここで非機能要件が&quot;新たに&quot;決まるのは、要件定義での詰めが甘かったサインである）</li></ul></li></ol><p>後から加わる相手（IT・運用など）には、それまでにリード担当者と合意した内容（優先度・停止影響など）を確実に共有する。また、（2）で誰を巻き込むかは、（1）のうちに段取っておくとよい。</p><h2 id="where" tabindex="-1">Where（適用範囲と境界をどう決めるか） <a class="header-anchor" href="#where" aria-label="Permalink to &quot;Where（適用範囲と境界をどう決めるか） {#where}&quot;">​</a></h2><p>本章の「Where」は、個々の非機能要件がどこに適用されるか（要件ごとの適用箇所）を指すのではない。一段上のメタな視点である、<strong>そもそも非機能要件を、システムのどの範囲について定義・保証するのか</strong>を扱う。個別の要件を詰める前に、まず「定義の対象範囲」そのものを線引きする章である。</p><p>対象範囲は、システム構造の観点で、次の2つを定める。</p><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">対象システム</td><td style="text-align:left;">自システムと外部との責任分界点（どのシステムまで保証するか）</td></tr><tr><td style="text-align:left;">対象環境</td><td style="text-align:left;">本番・検証・開発など、どの環境を、どのような前提で扱うか</td></tr></tbody></table><h3 id="対象システム-責任分界点" tabindex="-1">対象システム（責任分界点） <a class="header-anchor" href="#対象システム-責任分界点" aria-label="Permalink to &quot;対象システム（責任分界点）&quot;">​</a></h3><p>システムは、単独で完結することは少ない。より大きなシステムの一部であったり、外部のシステムに依存していたりする。そのため非機能要件は、システム単体ではなく、こうした周囲との関係で定める必要がある。次の3つの視点で整理する。</p><h4 id="全体を正とし、自分の範囲へ割り当てる" tabindex="-1">全体を正とし、自分の範囲へ割り当てる <a class="header-anchor" href="#全体を正とし、自分の範囲へ割り当てる" aria-label="Permalink to &quot;全体を正とし、自分の範囲へ割り当てる&quot;">​</a></h4><p>自分たちの構築範囲がシステム全体の一部（あるマイクロサービスやコンポーザブルな PBC など）である場合でも、まず全体の非機能要件（サービスレベル）を正とする。そこから自分たちの範囲が満たすべき要件を割り当てる。各要素で個別に決めた値を積み上げて全体を決めるのではない。全体のサービスレベルを、それを構成する各要素へ階層的に分解・設計していくことが肝要である。</p><p>ただし、割り当てた要件が各要素で実現可能かは、別途ボトムアップに検証する。要件の導出はトップダウン、実現性の確認はボトムアップ、と使い分ける。</p><h4 id="保証する範囲を多段で整理する" tabindex="-1">保証する範囲を多段で整理する <a class="header-anchor" href="#保証する範囲を多段で整理する" aria-label="Permalink to &quot;保証する範囲を多段で整理する&quot;">​</a></h4><p>外部に依存しているからといって「そこは範囲外」と切り捨てるのは、プロとして不十分である。外向きも含めて全体像を持ったうえで、保証する範囲を段階的に整理し、合意する。</p><ol><li><strong>全体の非機能要件を、設計上は定義する</strong><ul><li>外部依存も含めた全体として目指す水準（例: 画面応答はエンドツーエンドで3秒以内）を描く</li><li>保証できるか否かは別として、全体像を持つのがプロの責務である</li></ul></li><li><strong>自分たちが保証・検証する範囲を切り出す</strong><ul><li>そのうち、自システムが責任を持って担保し、非機能テストで検証する範囲を明確にする（例: 自システム内の処理は2秒以内）</li></ul></li><li><strong>外部依存の扱いを決める</strong><ul><li>保証できない外部について、前提（外部の SLA・想定応答時間）と、障害時の振る舞い（一緒に止めるか、縮退継続か）を整理して合意する</li></ul></li></ol><h4 id="外部に頭打ちされるなら、全体最適でレベルを調整する" tabindex="-1">外部に頭打ちされるなら、全体最適でレベルを調整する <a class="header-anchor" href="#外部に頭打ちされるなら、全体最適でレベルを調整する" aria-label="Permalink to &quot;外部に頭打ちされるなら、全体最適でレベルを調整する&quot;">​</a></h4><p>外部連携先に依存し、自分たちで制御できる範囲が限られる場合、自システムの領域だけ非機能レベルを高めても意味が薄い。全体の水準は、制御できない依存先に引っ張られて頭打ちになるためである。</p><p>例えば認証を外部IdP（Entra ID、Auth0 など）に依存する場合、IdP が停止すればログインできず、自システムをいくら高可用にしても全体は止まる。こうした依存先は「当たり前」すぎて見落とされやすい。全体の整合を見て、過不足のないレベルに調整する方が、投資対効果が高い。</p><h3 id="対象環境" tabindex="-1">対象環境 <a class="header-anchor" href="#対象環境" aria-label="Permalink to &quot;対象環境&quot;">​</a></h3><p>非機能要件、特にセキュリティやポリシー系の要件は、すべての環境に一律で適用されるわけではない。各環境が「外部とどれだけ接続しているか」「本番・機密データを扱うか」によって、適用すべき要件の範囲が変わる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">環境</th><th style="text-align:left;">特徴と要件適用方針</th></tr></thead><tbody><tr><td style="text-align:left;">本番</td><td style="text-align:left;">実データ・外部接続・本番利用者が揃うため、要件をフルに適用する。</td></tr><tr><td style="text-align:left;">検証</td><td style="text-align:left;">オンプレとの接続（専用線など）や実データを扱う場合、セキュリティ要件などは本番同様に適用する。</td></tr><tr><td style="text-align:left;">開発</td><td style="text-align:left;">ネットワーク的に隔離され実データを持たないサンドボックスであれば、一部のポリシー制約は緩和できる。</td></tr></tbody></table><p>環境ごとの前提は、後続フェーズの体制やインフラのボリュームにも直結する。どの要件を、どの環境に、どこまで適用するかを決めるため、各環境について少なくとも次の観点を確認する。</p><table tabindex="0"><thead><tr><th style="text-align:left;">項目</th><th style="text-align:left;">確認事項</th></tr></thead><tbody><tr><td style="text-align:left;">データ</td><td style="text-align:left;">本番データの利用可否、マスキングの要否</td></tr><tr><td style="text-align:left;">接続経路</td><td style="text-align:left;">リモート接続の可否、接続元端末の制限</td></tr><tr><td style="text-align:left;">オンプレとの接続方式</td><td style="text-align:left;">専用線や VPN の要否。特に専用線は開通までのリードタイムが長いため、早期に見極めが必要。</td></tr><tr><td style="text-align:left;">監査</td><td style="text-align:left;">監査ログの要否、保存要件（例: 本番は監査ログ必須）</td></tr><tr><td style="text-align:left;">権限</td><td style="text-align:left;">各環境にアクセスできる担当者の範囲</td></tr><tr><td style="text-align:left;">クラウドアカウント構造</td><td style="text-align:left;">ランディングゾーン・発行ルール・ガードレール（SCP など）の有無。新規アカウント作成の可否。<br>アカウント構造そのものの設計は基本設計の領域だが、要件定義段階ではどんな制約があるかという前提を確認する（発行・承認にリードタイムを要することも多いため）</td></tr></tbody></table><h2 id="how" tabindex="-1">How（非機能要件定義の実施） <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How（非機能要件定義の実施） {#how}&quot;">​</a></h2><p>本章では実際どのように非機能要件定義を進めるかを扱う。</p><h3 id="心得" tabindex="-1">心得 <a class="header-anchor" href="#心得" aria-label="Permalink to &quot;心得&quot;">​</a></h3><p>すべての品質を最高水準にはできない。限られたコストと期間の中で、個々の要件のレベルをどう決めるか。次の順に判断していく。まずトレードオフの構造を理解し（上げすぎには過剰品質という代償がある）、その中で重要な要件を見極め、決めた要件がその先へどう波及するかを見通す。</p><ul><li><strong>全てはトレードオフである</strong><ul><li>非機能要件には「全部を最高レベルで」という選択肢は存在しない。例えば、次のような関係がある <ul><li>可用性を99.99％まで引き上げれば、冗長化のコストと運用負荷が跳ね上がる</li><li>レスポンスを極限まで速くしようとすれば、アーキテクチャは複雑化し保守性が犠牲になる</li><li>セキュリティを強固にすれば、性能やユーザビリティが落ちる</li><li>運用の柔軟性を高めれば、統制が緩む</li></ul></li><li>ある品質を上げれば、別の品質、コスト、スケジュールのいずれかを必ず犠牲にする。そのため非機能要件を議論する際に避けるべきは、各項目を個別に判断することである。ひとつひとつは正しい判断に見えても、それが積み上がれば実現不可能なシステムになる</li><li>要件を検討する際に「その代償として何を諦めるのか」を必ずセットで言語化することが望ましい</li></ul></li><li><strong>過剰品質を避ける</strong><ul><li>非機能要件は不足ばかりが問題視されるが、過剰も同じくらい大きな問題を引き起こす。念のため可用性を高くする、念のためデータを暗号化するなど、念のための積み重ねは複雑度を上げて開発・運用保守コストが嵩み、リリースまでのスピードを犠牲にする。常に要件の根拠を問い、明確でない場合は過剰である可能性を疑い、必要十分を見極める</li></ul></li><li><strong>重要な要件を見つける</strong><ul><li>単に非機能要件を一覧化しただけで満足してはいけない。トレードオフを見出した先に必要となるのが「システムにとって本当に重要な非機能要件はどれか」を見極める作業である</li><li>重要な要件とは「あったほうがよい」ではなく「これが満たせなければシステムの存在意義が失われる」性質のものを指す。例えば、決済システムにとっての整合性と可用性、HFT（高頻度取引）システムにとってのレイテンシとスループットである</li><li>重要な要件を明確にしておくことで、アーキテクチャ設計をはじめとするあらゆる意思決定において、関係者間でブレなく何を優先すべきかをクイックに判断するための土台にできる</li><li>業務上のクリティカルな失敗シナリオを想像し、致命傷になり得るケースから非機能要件を逆算すると見えてくることが多い</li></ul></li><li><strong>非機能要件定義の先まで見通す</strong><ul><li>非機能要件定義は、それ単体で完結しない。決めた要件は、設計・構築・テスト検証へと波及する。要件を決めるときは、それがどんな設計を要し、コストや期間、後のテストにどう跳ね返るかを見通す必要がある。要件から設計を想像できてこそ、実現可能で過不足のない要件になる。逆に過剰な要件は、後工程のコストやスピードとして跳ね返る。その影響をビジネスゴールに照らして示し、抑えることも、リードする側の役割である（→「過剰品質を避ける」）</li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">「24時間365日」を安易に受け入れない</p><p>顧客は「24時間365日止めたくない」「無停止更新にしたい」といった要求を、コスト感を伴わないまま口にしがちである。しかしこれらは高コスト・高難易度であり、本当に必要かを疑ってかかる。求められるまま呑む「御用聞き」ではなく、その水準が何を犠牲にするか（コスト・スケジュール・運用負荷）を示し、身の丈に合った現実解へ落とすのがプロの役割である。</p></div><h3 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h3><p>非機能要件定義では「膨大な項目の網羅性をどう担保し、合意するか」が難しい。すべてを頭から均等に合意しようとすると時間が足りないので、メリハリをつけて段階的に進める必要がある。</p><p>以下に、非機能要件を定義するための思考の順序を示す。提案〜グラウンドデザインで大枠を先行して掴み（<a href="#step0">STEP0</a>）、要件定義フェーズ以降で各ステップを通して具体化・確定していく。ただし一方通行ではなく、後段の検討や検証の結果を受けて前段へ戻り、見直しながら固めていく（図の見直し矢印）。</p>',81)),(e(),d(o,null,{default:l(()=>[a(r,{id:"mermaid-1123",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20theme%3A%20neutral%0A%20%20look%3A%20handDrawn%0A---%0Aflowchart%20TB%0A%20%20%20%20subgraph%20G1%5B%22%E2%91%A0%20%E6%BA%96%E5%82%99%E3%81%A8%E5%89%8D%E6%8F%90%E6%8A%8A%E6%8F%A1%22%5D%0A%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20S0%5B%220.%20%E6%8F%90%E6%A1%88%E3%80%9CGD%3Cbr%2F%3E%EF%BC%88%E5%85%88%E8%A1%8C%E3%81%97%E3%81%A6%E5%A4%A7%E6%9E%A0%E3%82%92%E6%8E%B4%E3%82%80%EF%BC%89%22%5D%0A%20%20%20%20%20%20S1%5B%221.%20%E9%80%B2%E3%82%81%E6%96%B9%E3%81%AE%E5%90%88%E6%84%8F%22%5D%0A%20%20%20%20%20%20S2%5B%222.%20%E3%83%93%E3%82%B8%E3%83%8D%E3%82%B9%E3%82%B3%E3%83%B3%E3%83%86%E3%82%AD%E3%82%B9%E3%83%88%3Cbr%2F%3E%E7%90%86%E8%A7%A3%22%5D%0A%20%20%20%20%20%20S3%5B%223.%20%E5%88%B6%E7%B4%84%E3%81%AE%E6%B4%97%E3%81%84%E5%87%BA%E3%81%97%22%5D%0A%20%20%20%20%20%20S0%20--%3E%20S1%20--%3E%20S2%20--%3E%20S3%0A%20%20%20%20end%0A%20%20%20%20subgraph%20G2%5B%22%E2%91%A1%20%E6%A4%9C%E8%A8%8E%E3%81%AE%E9%AA%A8%E6%A0%BC%E3%81%A5%E3%81%8F%E3%82%8A%22%5D%0A%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20S4%5B%224.%20%E9%87%8D%E8%A6%81%E3%83%89%E3%83%A9%E3%82%A4%E3%83%90%E3%81%AE%E7%89%B9%E5%AE%9A%22%5D%0A%20%20%20%20%20%20S5%5B%225.%20%E3%83%95%E3%83%AC%E3%83%BC%E3%83%A0%E3%83%AF%E3%83%BC%E3%82%AF%E3%81%AE%E9%81%B8%E5%AE%9A%22%5D%0A%20%20%20%20%20%20S6%5B%226.%20%E3%83%99%E3%83%BC%E3%82%B9%E3%83%A9%E3%82%A4%E3%83%B3%E3%81%AE%E8%A8%AD%E5%AE%9A%22%5D%0A%20%20%20%20%20%20S4%20--%3E%20S5%20--%3E%20S6%0A%20%20%20%20end%0A%20%20%20%20subgraph%20G3%5B%22%E2%91%A2%20%E7%A2%BA%E5%AE%9A%E3%81%A8%E8%A8%AD%E8%A8%88%E3%81%B8%E3%81%AE%E5%B1%95%E9%96%8B%22%5D%0A%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20S7%5B%227.%20%E5%84%AA%E5%85%88%E5%BA%A6%E4%BB%98%E3%81%91%22%5D%0A%20%20%20%20%20%20S8%5B%228.%20%E8%A6%81%E6%B1%82%E3%81%AE%E5%AE%9A%E9%87%8F%E5%8C%96%22%5D%0A%20%20%20%20%20%20S9%5B%229.%20%E3%83%88%E3%83%AC%E3%83%BC%E3%83%89%E3%82%AA%E3%83%95%E3%81%AE%E8%A9%95%E4%BE%A1%22%5D%0A%20%20%20%20%20%20S10%5B%2210.%20%E3%82%B9%E3%83%86%E3%83%BC%E3%82%AF%E3%83%9B%E3%83%AB%E3%83%80%E3%83%BC%E5%90%88%E6%84%8F%22%5D%0A%20%20%20%20%20%20S11%5B%2211.%20%E3%82%A2%E3%83%BC%E3%82%AD%E3%83%86%E3%82%AF%E3%83%81%E3%83%A3%E8%A8%AD%E8%A8%88%E3%81%B8%E3%81%AE%E5%8F%8D%E6%98%A0%22%5D%0A%20%20%20%20%20%20S7%20--%3E%20S8%20--%3E%20S9%20--%3E%20S10%20--%3E%20S11%0A%20%20%20%20%20%20S9%20-.%E8%A6%8B%E7%9B%B4%E3%81%97.-%3E%20S7%0A%20%20%20%20%20%20S9%20-.%E8%A6%8B%E7%9B%B4%E3%81%97.-%3E%20S8%0A%20%20%20%20%20%20S11%20-.%E8%A6%8B%E7%9B%B4%E3%81%97.-%3E%20S8%0A%20%20%20%20end%0A%20%20%20%20G1%20--%3E%20G2%20--%3E%20G3%0A"})]),fallback:l(()=>[...t[1]||(t[1]=[n(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=i('<h4 id="step0" tabindex="-1">STEP0. 提案〜グラウンドデザイン（先行して大枠を掴む） <a class="header-anchor" href="#step0" aria-label="Permalink to &quot;STEP0. 提案〜グラウンドデザイン（先行して大枠を掴む） {#step0}&quot;">​</a></h4><ul><li>重要ドライバに関連しそうなビジネス上の関心事や大枠の予算・体制といった方針レベルを粗く押さえる（→ <a href="#when">When章</a>）</li><li>予算・方針を決める意思決定層を中心に、主要な利害関係者を特定・巻き込む（→ <a href="#who">Who章</a>）</li></ul><h4 id="step1" tabindex="-1">STEP1. 進め方の合意 <a class="header-anchor" href="#step1" aria-label="Permalink to &quot;STEP1. 進め方の合意 {#step1}&quot;">​</a></h4><p>要件定義フェーズの入口として、このフローチャートにあるような進め方そのものを関係者と合意する。</p><h4 id="step2" tabindex="-1">STEP2. ビジネスコンテキストの理解 <a class="header-anchor" href="#step2" aria-label="Permalink to &quot;STEP2. ビジネスコンテキストの理解 {#step2}&quot;">​</a></h4><p>非機能要件定義の着手前に、対象とするシステムがビジネス上どのような意味を持ち、どのような前提のもとで何を達成したいのかを明確に理解することが重要である。ビジネスコンテキストを理解せずに定義された非機能要件は判断軸を欠き、妥当性を問われたとき根拠が示せない。</p><p>具体的には、次のような観点を押さえておきたい。</p><table tabindex="0"><thead><tr><th style="text-align:left;">観点</th><th style="text-align:left;">具体例</th></tr></thead><tbody><tr><td style="text-align:left;">ビジネスゴール</td><td style="text-align:left;">このシステムで事業として何を成したいか。「新規事業で顧客数を一気に伸ばす（攻め）」「既存業務のコストを削る（守り）」「老朽システムを刷新し、スピードと保守性を取り戻す」など。攻めか守りかで、可用性・性能・拡張性への投資姿勢が変わる。</td></tr><tr><td style="text-align:left;">ビジネス上のクリティカル度</td><td style="text-align:left;">止まったとき事業にどれだけ響くか。「決済・受発注のように、停止が即・売上と信用の毀損に直結する基幹業務」か「社内の情報共有のように、多少の停止は許容される業務」か。</td></tr><tr><td style="text-align:left;">ユーザー像と利用規模</td><td style="text-align:left;">社内数百名の業務利用か、不特定多数の toC 数百万規模か（精緻な数値は <a href="#step8">STEP8</a> で定量化する）。</td></tr><tr><td style="text-align:left;">コストやスケジュール感</td><td style="text-align:left;">予算・納期がどの程度タイトか。潤沢か、厳しい上限があるか。</td></tr><tr><td style="text-align:left;">新規構築か現行刷新か</td><td style="text-align:left;">刷新なら、現行の実績値・障害履歴が使える（→ <a href="#who">Who章「現行システムの運用者」</a>）。また、既知の課題の解消が焦点になる。新規なら、拠り所となる実績がなく、構築コストと見込み効果のバランスから水準を起こす。</td></tr></tbody></table><p>これらは非機能要件定義に着手する段階である程度明確になっていることが多く、関係者間の共通のメンタルモデルとなる。</p><h4 id="step3" tabindex="-1">STEP3. 制約の洗い出し <a class="header-anchor" href="#step3" aria-label="Permalink to &quot;STEP3. 制約の洗い出し {#step3}&quot;">​</a></h4><p>ビジネスコンテキストを理解したら、次に「すでに存在し、変更できない制約」を早期に洗い出す。<a href="#what">What章</a>で触れたとおり、制約はビジネス制約と技術制約に分かれる。そのうち予算・スケジュール・体制などのビジネス制約は <a href="#step2">STEP2</a> で大枠を把握しているとする。ここでは、後から発覚すると手戻りの大きい技術・規程系の制約を中心に押さえる。</p><p>なお制約の出所は、非機能要件とは別の担当者であることも多い（→ <a href="#who">Who章</a>）。</p><h5 id="採用技術の事前決定が無いかの確認" tabindex="-1">採用技術の事前決定が無いかの確認 <a class="header-anchor" href="#採用技術の事前決定が無いかの確認" aria-label="Permalink to &quot;採用技術の事前決定が無いかの確認&quot;">​</a></h5><p>教科書的には「非機能要件を定義した後に、それを満たすアーキテクチャや採用技術（例: AWS、Java、PostgreSQL など）を選ぶ」のが理想とされる。しかし実態としては、業界や組織の標準化戦略、既存ライセンス、ベンダーの都合などにより、要件定義の開始時点でコアの技術スタックやミドルウェア（例: JP1 など）が既に決まっているケースが多い。これらは議論の余地のない前提条件となり、後で発覚すると手戻りになるため、初期にこうした縛りがないかを確認する。</p><div class="tip custom-block"><p class="custom-block-title">既存技術スタックという&quot;暗黙の制約&quot;</p><p>明文化された言語・フレームワークの縛りがなくても、既存システムとの整合そのものが事実上の制約になる。周囲がすべて Java なのに、ある部分だけ Python や Go を採ると、運用・保守・要員確保の負荷が上がり、選びにくい。ここには非対称性がある。<strong>既存スタックを踏襲する場合、説明を省略できるが、そこから外れる選択には「なぜそれを選ぶのか」の説明責任が生じる</strong>。この差を意識しておきたい。</p><p>新しい技術を試す組織の許容度（予算）は有限である。そのため、顧客組織に馴染みのない技術を導入する場合は、あれもこれもと広げず、効果の大きい領域に戦略的に絞り、前述の説明コストも織り込んだうえで可否を検討する。</p></div><div class="tip custom-block"><p class="custom-block-title">ベンダーロックイン</p><p>「特定ベンダーにロックインしたくない」「採用は GA 版に限る」「なるべくマネージドや SaaS に寄せたい」といった方針は、明文化されないまま技術選定を縛る、隠れた制約になりやすい。永続性（EOL リスク）への許容度も含め、組織のスタンスとして早期に確認しておく。</p><p>ただし、ロックインの回避が無条件で良いことではない。移植性を追えば、マネージドサービスがもたらす保守性・セキュリティ・スピードを手放し、逆にすれば依存は深まる。いずれもトレードオフであり、避けたいという考えを絶対要求にせず、便益と天秤にかけて必要な範囲を見極める（→ 心得「過剰品質を避ける」）。</p></div><h5 id="規定ドキュメントの確認" tabindex="-1">規定ドキュメントの確認 <a class="header-anchor" href="#規定ドキュメントの確認" aria-label="Permalink to &quot;規定ドキュメントの確認&quot;">​</a></h5><p>顧客組織内に次のような規定ドキュメント（ガイドライン・ポリシー）が存在するかどうかが、その後の検討作業量を大きく左右する。</p><ul><li>クラウド構築ガイドライン（CCoEなどが策定した標準ルール）</li><li>全社セキュリティポリシー</li><li>システム運用標準基準書</li></ul><p>これら規定ドキュメントの有無でアプローチが変わる。</p><ul><li><strong>ある場合</strong>: 準拠が絶対条件となる。ゼロから非機能要件を考えるのではなく、「規定を遵守した上で、今回のシステム特有の要件をどう上乗せするか」という差分のアプローチをとる。</li><li><strong>ない場合</strong>: パブリッククラウドのベストプラクティス（AWS Well-Architected Frameworkなど）や、業界標準の基準を拠り所としてアーキテクチャ設計のベースラインを構築する。</li></ul><h4 id="step4" tabindex="-1">STEP4. 重要ドライバの特定 <a class="header-anchor" href="#step4" aria-label="Permalink to &quot;STEP4. 重要ドライバの特定 {#step4}&quot;">​</a></h4><p>まず、このシステムで何を最優先するのかという方向を固め、そこからアーキテクチャ設計を左右する重要ドライバへ具体化する。関係者を集めて重点的に議論するのは、この重要ドライバである。それ以外の項目はベースライン（<a href="#step6">STEP6</a>）や書面確認に委ねて、メリハリをつける。</p><h5 id="システムのコンセプトを固める" tabindex="-1">システムのコンセプトを固める <a class="header-anchor" href="#システムのコンセプトを固める" aria-label="Permalink to &quot;システムのコンセプトを固める&quot;">​</a></h5><p>重要ドライバを決めるために有効な問いは、「このシステムのコンセプトは何か？」である。ビジネスコンテキスト（<a href="#step2">STEP2</a>）を踏まえてこの問いに答えることで、各要件を仮説として立てる際の &quot;どちらへ寄せるか&quot; の指針になる。答えは、例えば次のようなものである。</p><ul><li>「EC セールのピークに耐える、性能・拡張性ファースト」</li><li>「絶対に障害で使えない時間を許容できない、可用性ファースト」</li><li>「運用・拡張のしやすさを最優先」</li><li>「とにかく情報流出を許さない、セキュリティファースト」</li><li>「コストをできる限り抑えたい」</li></ul><p>コンセプトが定まっていると、要件どうしが競合したときの寄せ方が決まり（例: セキュリティファーストなら、性能と競合したらセキュリティを優先）、トレードオフの初期判断が速くなる（→ 心得「全てはトレードオフである」）。</p><h5 id="アーキテクチャ設計に効く粒度まで掘る" tabindex="-1">アーキテクチャ設計に効く粒度まで掘る <a class="header-anchor" href="#アーキテクチャ設計に効く粒度まで掘る" aria-label="Permalink to &quot;アーキテクチャ設計に効く粒度まで掘る&quot;">​</a></h5><p>コンセプトは「性能が大事」で止めず、アーキテクチャ設計の分岐に直結する具体的なレベルまで掘り下げる。ここが曖昧だと、設計フェーズで手戻りになる。</p><ul><li><strong>性能ファースト</strong> → 処理の非同期化をどこまで許容するか（同期の即時応答が必須か、非同期・結果整合で許容されるか）</li><li><strong>可用性ファースト</strong> → どこまでの障害を無停止で耐えるか（マルチ AZ 冗長以上の、マルチリージョン / DR まで要るか）</li><li><strong>セキュリティファースト</strong> → マルチテナントの分離レベルをどこまで求めるか（論理分離で足りるか、DB・インスタンスレベルの物理分離まで要るか）</li></ul><h4 id="step5" tabindex="-1">STEP5. フレームワークの選定 <a class="header-anchor" href="#step5" aria-label="Permalink to &quot;STEP5. フレームワークの選定 {#step5}&quot;">​</a></h4><p>非機能要件の項目は多岐にわたるため、ゼロから洗い出すのではなく、業界標準の「フレームワーク」をベースラインとして活用することが一般的である。詳細は <a href="./appendix.html#非機能フレームワーク">Appendix: 非機能フレームワーク</a> を参照。</p><p>以下の手順で、検討の出発点とするフレームワークを選ぶ。</p><ol><li><strong>既存フレームワークの有無を調査する</strong><br> 顧客（もしくは自社）の組織内で、既に慣習的に利用されているフレームワークがあることも多い。そのため、まずはゼロベースで選定するのではなく、既存資産の流用から始めるのが現実的である。</li><li><strong>ドメインのデファクトスタンダードを基準に置く</strong><br> 対象システムが属するドメインにおいて、所与の出発点として扱われるフレームワークがある場合はそれをベースに置く。例えば、国内の一般的な業務システムであれば「IPA 非機能要求グレード」や「ISO/IEC 25010」、政府系システムであれば「デジタル社会推進標準ガイドライン（群）」が該当する。</li><li><strong>システムの特性に合わせて足りない観点を補強する</strong><br> 定めたベースを盲目的に採用するのではなく、システムの性質を踏まえて観点をブラッシュアップすることが腕の見せ所である。例えば「IPA 非機能要求グレード」はシステム基盤に特化しているため、エンドユーザー視点やアプリケーション視点（ユーザビリティ、アクセシビリティ、テスタビリティ、オブザーバビリティなど）をカバーしていない。システムの特性上これらが重要な意味を持つ場合は、「ISO/IEC 25010」などから観点を追加で取り込むか、独自項目として補強する。</li></ol><p>ここで強調しておきたい。フレームワークは、大きな抜け漏れを防ぐための補完的な道具であって、それに沿って項目を上から埋めていくための台帳ではない。よくある罠は、項目が並んでいるとつい頭から順に埋めたくなり、消化することが目的化してしまうケースである。本来は、本当に重要な要件を見落とさないよう、検討の抜けを点検する網羅性チェックとして用いる。優先順位づけの主役はシステム固有の重要ドライバ（→ <a href="#step4">STEP4</a>）に据える。</p><h4 id="step6" tabindex="-1">STEP6. ベースラインの設定 <a class="header-anchor" href="#step6" aria-label="Permalink to &quot;STEP6. ベースラインの設定 {#step6}&quot;">​</a></h4><p>個別の要件レベルを議論する前に、拠り所となる要求レベルのベースラインを仮置きする。ベースラインがないまま項目ごとに議論すると、ゼロから1つずつ妥当性を問うことになり、空中戦になりやすい。</p><p>ベースラインには、既存・類似システムの非機能要求や、フレームワーク（<a href="#step5">STEP5</a>）が用意する標準モデルを使う。IPA 非機能要求グレードなら、社会的影響の大きさに応じた3つのモデルシステム（ほとんどない / 限定される / 極めて大きい）が用意されている。<a href="#step4">STEP4</a> で見極めたコンセプト・重要度に最も合うものを選ぶ作業が、これに当たる。</p><p>ただし、こうした標準モデルは粒度が粗く、対象システムの実態と噛み合わないことも多い。あくまで初期値・網羅チェックと割り切り、そのまま当てはめない。ベースラインをもとに、システムの性質を踏まえて必要な部分を個別に調整していく。</p><h4 id="step7" tabindex="-1">STEP7. 優先度付け <a class="header-anchor" href="#step7" aria-label="Permalink to &quot;STEP7. 優先度付け {#step7}&quot;">​</a></h4><p>重要ドライバとベースラインで洗い出した要件・制約を、フラットに扱わず、次の3レベルに分類して関係者間で認識を合わせる。ここで付けた優先度が、後段のトレードオフ評価（<a href="#step9">STEP9</a>）で「どこを緩められるか」の交渉材料になる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">要件レベル</th><th style="text-align:left;">定義・内容</th></tr></thead><tbody><tr><td style="text-align:left;">Must要件</td><td style="text-align:left;">遵守が絶対条件。満たさなければプロジェクト自体が成立しない（例: 予算の上限、法規制の遵守）</td></tr><tr><td style="text-align:left;">Should要件</td><td style="text-align:left;">強く求められるが、状況によっては交渉や代替案を提示できる条件（例: 目標とするレスポンスタイム）。要件を緩めて構築・ランニングコストを下げられるなら、交渉の余地は大きい</td></tr><tr><td style="text-align:left;">Want要件</td><td style="text-align:left;">必須ではないが、コストやスケジュールに余裕があれば実現したい条件（例: 将来の拡張に向けたリソース確保）</td></tr></tbody></table><h4 id="step8" tabindex="-1">STEP8. 要求の定量化 <a class="header-anchor" href="#step8" aria-label="Permalink to &quot;STEP8. 要求の定量化 {#step8}&quot;">​</a></h4><p>重要ドライバをはじめ、優先度付けした要件を具体的なシステムの目標値へと落とし込む。ここで立ちはだかるのが、「定性的なビジネスの要望を、システムの定量的なロジックに変換し、合意形成に持っていく」という翻訳の壁である。顧客から自然と具体的な数値（TPSやRTOなど）が出てくることは稀である。構築側がロジックを組み立てて合意へ導く必要がある。</p><h5 id="基礎数値" tabindex="-1">基礎数値 <a class="header-anchor" href="#基礎数値" aria-label="Permalink to &quot;基礎数値&quot;">​</a></h5><p>定量化の土台となるのが、ビジネス側から引き出す基礎数値である。利用者や業務そのものの洗い出しは機能要件定義で行われている前提で、ここではそれを入力に、非機能に効く数値を押さえる。</p><table tabindex="0"><thead><tr><th style="text-align:left;">基礎数値</th><th style="text-align:left;">具体例</th><th style="text-align:left;">影響する非機能</th></tr></thead><tbody><tr><td style="text-align:left;">規模</td><td style="text-align:left;">利用者1万人・拠点50・データ量○TB</td><td style="text-align:left;">性能・拡張性（TPS など）の土台</td></tr><tr><td style="text-align:left;">地理的範囲</td><td style="text-align:left;">国内一拠点か、グローバルか</td><td style="text-align:left;">ネットワーク環境（海外レイテンシなど）</td></tr><tr><td style="text-align:left;">時間的範囲</td><td style="text-align:left;">平日日中のみか、24時間365日か</td><td style="text-align:left;">担保すべき稼働時間</td></tr><tr><td style="text-align:left;">ピーク特性</td><td style="text-align:left;">通常の何倍か（セール・決算期など）</td><td style="text-align:left;">ピーク時の性能目標</td></tr></tbody></table><p>現行システムがあれば、その実績値（トラフィック・障害履歴）が最良の基礎数値になる（→ <a href="#who">Who章「現行システムの運用者」</a>）。新規構築なら、事業計画から見込みを起こす。</p><h5 id="ヒアリングのコツ" tabindex="-1">ヒアリングのコツ <a class="header-anchor" href="#ヒアリングのコツ" aria-label="Permalink to &quot;ヒアリングのコツ&quot;">​</a></h5><p>顧客に「ピーク時のTPSは？」と専門用語で問いかけても、ハレーションを生むだけである。聞き方を工夫し、吸い出した情報を要件へ組み立てる必要がある。</p><ul><li><strong>目的を説明する</strong><ul><li>基礎数値の収集周りで顕著だが、なぜこの質問を受けているかが理解できていないと、協力姿勢にはなりにくい</li><li>取得した基礎数値をどの様な目的で利用するか（システム要件に落とし込み、性能検証で担保するため）を必ず示す</li></ul></li><li><strong>仮説をもってリードする</strong><ul><li>非機能要件は、顧客に「どうしますか？」と受け身で尋ねても出てくるものではない</li><li>顧客から具体的な数値が出てこない場合は、構築側から「御社の事業規模と今後の成長率を考慮すると、このような想定値になりますが実態と合っていますか？」と、叩き台となる仮説を必ず提示する。仮説がなければ、要件は引き出せない</li></ul></li><li><strong>計算式からストーリーを作る</strong><ul><li>ビジネス要件から技術要件（TPS など）を導出する計算式を、顧客と共有する。例: 「ピーク時の想定同時接続1,000名 ÷ 10秒に1回クリック = 100 TPS」</li><li>ただし数値の算出で終わらせない。その数値が「なぜその水準なのか」「満たせない / 満たすとシステムや利用者に何が起きるのか」まで語る。単なる穴埋めにせず、腹落ちする合意に持っていく</li></ul></li></ul><p>定量化のゴールは、テストで検証できる数値にすることである。目標値を置いたら、それが <a href="#テストフェーズとの連携">Why章「テストフェーズとの連携」</a>のどのテストで確認できるかをセットで押さえる。対応するテストを描けない目標値は、定義がまだ曖昧なサインである。</p><h4 id="step9" tabindex="-1">STEP9. トレードオフの評価 <a class="header-anchor" href="#step9" aria-label="Permalink to &quot;STEP9. トレードオフの評価 {#step9}&quot;">​</a></h4><p>定量化・優先度付けした要件を、個別ではなく全体として突き合わせ、コスト・スケジュールの中で成立するかを評価する。単体で見ると妥当な要件でも、積み上げると実現不可能になることが多い（→ 心得「全てはトレードオフである」）。</p><p>評価は次の順で行う。</p><ol><li><strong>競合を洗い出す</strong>: どの要件どうしがぶつかるのかを明示する（例: 可用性↑はコスト↑、セキュリティ↑は性能・ユーザビリティ↓）。個別に見ていると気づけないため、一覧にして横断で見る</li><li><strong>重要ドライバを軸に裁定する</strong>: 要件が競合したら、<a href="#step4">STEP4</a> の重要ドライバ・コンセプトに照らしてどちらを立てるかを決める。コンセプトが「セキュリティファースト」なら、性能と競合したときはセキュリティを取る</li><li><strong>優先度で緩める要件を選ぶ</strong>: コスト・スケジュールに収まらなければ、Should/Want から緩める。Must には手を付けない。「コスト」が最重要ドライバである場合、他の非機能要件（可用性や性能など）をどこまでShould/Wantに妥協・ダウングレードできるかが、アーキテクチャ設計の鍵となる</li></ol><p>それでも全体が破綻する場合は、優先度付け（<a href="#step7">STEP7</a>）や目標値（<a href="#step8">STEP8</a>）に戻って水準を調整する。</p><h4 id="step10" tabindex="-1">STEP10. ステークホルダー合意 <a class="header-anchor" href="#step10" aria-label="Permalink to &quot;STEP10. ステークホルダー合意 {#step10}&quot;">​</a></h4><p>評価を通った要件を、関係者と正式に合意し、確定させる。誰と・どの場で合意するかは <a href="#who">Who章</a>・<a href="#when">When章</a>を参照。</p><p>各目標値は、次の3点を満たして初めて「確定」とする。</p><ol><li><strong>業務要求に照らして合理的か</strong>: なぜその水準なのかを、ビジネスの根拠で説明できる</li><li><strong>実現可能か</strong>: その値を達成できる設計が、合理的に描けている</li><li><strong>未達時に原因を説明し、改善できるか</strong>: 達成できなかったとき、原因を追い、手を打てる</li></ol><p>また、合意の対象は目標値そのものだけではない。その値を「どう測るか」という前提も、あわせて決めておく。測り方が曖昧なままだと、同じ実績を前にして達成・未達の判断が食い違う。例えば稼働率ではその計算式を要件合意の時点で明確にしておく（→ 第二部 <a href="./availability.html">可用性</a>）。</p><p>合意した値は、根拠（重要ドライバ・基礎数値・トレードオフの結果）とセットで記録する。後段の設計や将来の保守でなぜこの値になったかを辿れるようにするためである（→ <a href="#継承">Why章「継承」</a>）。</p><h4 id="step11" tabindex="-1">STEP11. アーキテクチャ設計への反映 <a class="header-anchor" href="#step11" aria-label="Permalink to &quot;STEP11. アーキテクチャ設計への反映 {#step11}&quot;">​</a></h4><p>確定した非機能要件を、ドキュメント化して基本設計以降へ引き渡す。設計・検証の中で実現困難が判明したら、要件へフィードバックし、再調整する。</p>',65))])}const P=E(p,[["render",f]]);export{B as __pageData,P as default};
